namespace sv_6986d18ba27b4da8b9f6854c80001c23.Services;

/// <summary>
/// Scoped service holding the currently selected warehouse.
/// Each circuit (user session) gets its own instance, so managers
/// never interfere with each other's selection.
/// </summary>
public class WarehouseState
{
    public string SelectedWarehouseId { get; private set; } = "warehouse-a";

    public event Action? OnChange;

    public static IReadOnlyList<(string Id, string Name)> AvailableWarehouses { get; } =
    [
        ("warehouse-a", "Warehouse A"),
        ("warehouse-b", "Warehouse B"),
        ("warehouse-c", "Warehouse C"),
    ];

    public void SetWarehouse(string warehouseId)
    {
        if (SelectedWarehouseId == warehouseId) return;
        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_6986d18ba27b4da8b9f6854c80001c23.Services;

/// <summary>
/// Scoped service that provides low-stock alert counts.
/// Polling is driven by a component (the Dashboard); when new data
/// arrives, all subscribers (sidebar badge, dashboard, etc.) are
/// notified through the OnAlertCountChanged event.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly Random _random = new();

    public int LastAlertCount { get; private set; }

    /// <summary>
    /// Fired after <see cref="RefreshAlertCountAsync"/> completes.
    /// Subscribers must wrap StateHasChanged in InvokeAsync because
    /// this fires from a timer (non-Blazor thread).
    /// </summary>
    public event Action? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query returning the number of items
    /// below minimum stock levels for the given warehouse.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches the latest alert count and notifies all subscribers.
    /// </summary>
    public async Task RefreshAlertCountAsync(string warehouseId)
    {
        LastAlertCount = await GetLowStockCountAsync(warehouseId);
        OnAlertCountChanged?.Invoke();
    }

    public void Dispose()
    {
        OnAlertCountChanged = null;
    }
}

