@using sv_6986d18ba27b4da8b9f6854c80001c23.Services
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<p>
    Currently viewing:
    <strong>@CurrentWarehouseName</strong>
</p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        @if (AlertService.LastAlertCount == 0)
        {
            <p class="text-success mb-0">✔ All items are sufficiently stocked.</p>
        }
        else
        {
            <p class="text-danger mb-0">
                ⚠ <strong>@AlertService.LastAlertCount</strong> item(s) below minimum stock level.
            </p>
        }
        <small class="text-muted">Refreshes every 10 seconds</small>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;

    private string CurrentWarehouseName =>
        WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId)
            .Name ?? WarehouseState.SelectedWarehouseId;

    protected override async Task OnInitializedAsync()
    {
        // Subscribe to warehouse changes so we refresh immediately on switch
        WarehouseState.OnChange += OnWarehouseChanged;

        // Subscribe to alert updates from any source
        AlertService.OnAlertCountChanged += OnAlertCountChanged;

        // Initial fetch
        await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);

        // Start polling
        _cts = new CancellationTokenSource();
        _ = PollAsync(_cts.Token);
    }

    private async Task PollAsync(CancellationToken ct)
    {
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        try
        {
            while (await _timer.WaitForNextTickAsync(ct))
            {
                await InvokeAsync(async () =>
                {
                    await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
                });
            }
        }
        catch (OperationCanceledException)
        {
            // Expected on dispose
        }
    }

    private void OnWarehouseChanged()
    {
        InvokeAsync(async () =>
        {
            await AlertService.RefreshAlertCountAsync(WarehouseState.SelectedWarehouseId);
            StateHasChanged();
        });
    }

    private void OnAlertCountChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertCountChanged;
        _cts?.Cancel();
        _cts?.Dispose();
        _timer?.Dispose();
    }
}
